      "description": "This is not valid ATProto DID validation. It accepts malformed values such as `did:m1:value` and `did:plc:%`, permits invalid percent escapes, and has no protocol length limit. Those inputs consequently pass route and AT-URI construction despite being unusable for PDS resolution.",
      "location": "src/utils/standard-site-paths.ts:15",
      "codePart": "const DID_RE = /^did:[a-z0-9]+:[A-Za-z0-9._:%-]+(?::[A-Za-z0-9._:%-]+)*$/;",
      "severity": 3,
      "confidence": 0.98
    },
    {
      "issueCode": "logic_error",
      "description": "An AT-URI collection must be a valid normalized NSID, but this parser checks only that the collection is nonempty. For example, it accepts `at://did:plc:REDACTED/not an nsid/3mabcde234567`, so malformed record URIs pass the claimed runtime validation.",
      "location": "src/utils/standard-site-paths.ts:32",
      "codePart": "export function parseAtUri(uri: string): AtUriParts | null {\n  const match = /^at:\\/\\/(did:[^/]+)\\/([^/]+)\\/([^/?#]+)$/.exec(uri);\n  if (!match) return null;\n  const [, did, collection, rkey] = match;\n  if (!isAtprotoDid(did) || !collection || !isTid(rkey)) return null;\n  return { did, collection, rkey };\n}",
      "severity": 3,
      "confidence": 0.99
    }
  ]
}

